def render(lang='en'):
 t=LABELS[lang]; e=html.escape
 cards=''.join(f'<article class="box"><h3>{e(c["name"])}</h3><p><b>+{(c["prices"][-1]/c["prices"][0]-1)*100:,.2f}%</b> · {e(t["pricegain"])}</p><p>{e(c["notes"][lang])}</p></article>' for c in CASES)
 links=f'<a href="{SOURCES["factbook"]}">GSE 2024 factbook</a> · <a href="{SOURCES["gse2025"]}">GSE December 2025</a> · <a href="{SOURCES["mtn"]}">MTN FY2025</a>'
 return f'<section class="sec" id="research" aria-labelledby="research-h" data-no-tr><div class="wrap"><div id="investor-research"><h2 id="research-h">{e(t["heading"])}</h2><p class="lead">{e(t["intro"])}</p><h3>{e(t["companies"])}</h3><p>{e(t["caseintro"])}</p><div class="grid2">{cards}</div><p class="src">{links}</p></div><script id="investor-content" type="application/json">{json.dumps(dict(labels=LABELS,cases=CASES,sectors=SECTORS,sources=SOURCES),ensure_ascii=False).replace("<","\\u003c")}</script></div></section>'
